private JointLockFileResponse toJointLockResponse(LockFileRow row) {
    List<RootView> roots = repositoryDao.listLockRoots(row.id()).stream()
            .map(r -> new RootView(r.name(), r.version())).toList();
    List<LockEntryResponse> entries = repositoryDao.listLockEntries(row.id()).stream()
            .map(e -> new LockEntryResponse(e.name(), e.version())).toList();
    List<EdgeView> edges = repositoryDao.listLockEdges(row.id()).stream()
            .map(e -> new EdgeView(e.fromName(), e.toName(), e.minimumVersion(), e.maximumVersion()))
            .toList();
    return new JointLockFileResponse(row.id(), roots, row.repositoryVersion(), row.createdAt(), entries, edges);
}
