    // 数据库实际冻结：根、条目、边各自行数正确。
    assertThat(jdbcTemplate.queryForObject(
            "SELECT COUNT(1) FROM lock_file_root WHERE lock_file_id = ?",
            Integer.class, lock.id())).isEqualTo(2);
    assertThat(jdbcTemplate.queryForObject(
            "SELECT COUNT(1) FROM lock_file_edge WHERE lock_file_id = ?",
            Integer.class, lock.id())).isEqualTo(2);
